    "id": "om654920-e350d-4cyl",
    "brand": "Mercedes-Benz",
    "model": "E 350 d (Asian Market)",
    "generation": "W213 (2018-2023) - Pre-Facelift / Facelift",
    "engineCode": "OM 654.920",
    "profileId": "om654920-e350d-4cyl",
    "displacement": "1,950 cc",
