    "engineeringData": {
      "blockDesign": "Inline 4-cylinder die-cast aluminum alloy block (EN AC-AlSi9Cu3) featuring centrifugally cast iron cylinder liners for enhanced durability under high cylinder pressures. The crankcase incorporates a Lanchester balancer system with dual counter-rotating shafts turning at twice the crankshaft speed to eliminate secondary inertial forces, delivering exceptional smoothness.",
      "crankshaft": "Forged micro-alloyed steel crankshaft with five main bearings and eight counterweights. The journals are induction-hardened to withstand the increased Brake Mean Effective Pressure (BMEP) of the CGI turbo system.",
      "pistonSpeed": "14.2 m/s @ 5000 RPM. The cast aluminum pistons feature graphite-coated skirts for friction reduction and an internal annular cooling gallery where high-pressure oil jets continuously spray to manage crown temperatures during prolonged boost.",
      "alternator": "150A Bosch high-efficiency unit utilizing a freewheeling pulley and intelligent LIN-bus battery management, decoupling under heavy acceleration to reduce parasitic drag on the engine.",
      "rotatingAssembly": { "pistonConstruction": "Cast aluminum with internal cooling galleries.", "wristPinDiameter": "22 mm.", "connectingRodLength": "143 mm.", "crankMainJournal": "58.0 mm.", "rodRatio": "1.64" },
      "cylinderHead": { "combustionChamberVol": "DOHC architecture. High-flow aluminum alloy cylinder head featuring optimized swirl and tumble port geometries tailored specifically for spray-guided direct injection.", "intakePortFlow": "Equipped with continuous hydraulic vane-type camshaft adjusters offering a 40-degree crank angle adjustment range.", "valveSizes": "Intake: 32.0 mm / Exhaust: 28.0 mm.", "lifterType": "Hydraulic bucket tappets with roller rocker arms." },
      "oilAndCooling": { "oilSquirters": "Yes, dedicated high-pressure jets targeting the piston crowns.", "oilPumpType": "Compact, chain-driven internal gear oil pump.", "thermostatOpening": "Electronically mapped. Operates between 90°C under heavy load and 105°C during light cruising to maximize thermodynamic efficiency.", "oilCooler": "Water-to-oil heat exchanger located near the oil filter housing." },
      "fuelSystem": { "systemType": "Spray-guided homogeneous Direct Injection (CGI) system utilizing outward-opening piezo-electric injectors.", "maxPressure": "140 Bar.", "injectors": "Piezo-electric multi-hole design capable of multiple injections per combustion cycle." },
      "tuningLimits": { "maxSafeTorqueStock": "380 Nm", "maxSafePowerStock": "260 hp", "weakestLink": "The extremely fragile simplex timing chain system and high-pressure fuel pump flow limits." },
      "electrical": { "coils": "4 individual coil-on-plug units.", "ecu": "Siemens SIM271DE2.0 featuring multi-spark ignition capabilities. The ECU can trigger the ignition coils up to four times within a single millisecond to ensure complete combustion of the lean stratified charge." }
    },
