    "engineeringData": {
      "blockDesign": "90-degree V6 cast aluminum block featuring highly durable Silitec silicon-aluminum cylinder liners. To counteract the inherent primary and secondary vibrations of the 90-degree V6 layout, Mercedes integrated a heavy-duty counter-rotating balance shaft mounted deep within the valley of the cylinder banks, ensuring velvety smooth operation across the RPM range.",
      "crankshaft": "Forged steel, micro-alloyed crankshaft supported by 4 robust main bearings. Features complex split-pin journals to accommodate the 90-degree firing intervals perfectly.",
      "pistonSpeed": "14.5 m/s @ 6000 RPM. Designed for long-lasting, smooth, and highly refined cruising operation rather than high-RPM performance.",
      "alternator": "150A Bosch heavy-duty unit.",
      "rotatingAssembly": { "pistonConstruction": "Cast aluminum with specialized iron coating to reduce friction against the Silitec liners.", "wristPinDiameter": "24 mm.", "connectingRodLength": "144 mm.", "crankMainJournal": "63.0 mm.", "rodRatio": "1.67" },
      "cylinderHead": { "combustionChamberVol": "DOHC, 4-valve per cylinder with continuous, stepless Variable Valve Timing on both the intake and exhaust camshafts to optimize the torque curve.", "intakePortFlow": "Equipped with a highly complex dual-stage, variable-length magnesium intake manifold using internal tumble flaps to maximize low-end torque and high-end horsepower.", "valveSizes": "Intake: 35.0 mm / Exhaust: 30.0 mm.", "lifterType": "Maintenance-free hydraulic bucket tappets." },
      "oilAndCooling": { "oilSquirters": "Yes, dedicated high-pressure jets targeting the underside of the piston crowns for thermal management.", "oilPumpType": "Reliable chain-driven internal gear pump.", "thermostatOpening": "90°C (Electronically mapped to increase temperatures under light load for fuel efficiency).", "oilCooler": "High-efficiency water-to-oil heat exchanger." },
      "fuelSystem": { "systemType": "Sequential Multi-Port Fuel Injection (MPI) completely avoiding direct injection carbon issues.", "maxPressure": "3.8 Bar.", "injectors": "Solenoid-operated, multi-hole design." },
      "tuningLimits": { "maxSafeTorqueStock": "400 Nm", "maxSafePowerStock": "330 hp", "weakestLink": "Lack of forced induction limits power gains entirely." },
      "electrical": { "coils": "6 individual high-energy coil-on-plug units.", "ecu": "Bosch ME9.7 managing variable valve timing and the complex variable intake manifold resonance system." }
    },
