    "engineeringData": {
      "blockDesign": "State-of-the-art inline 6-cylinder all-aluminum block featuring Nanoslide twin-wire arc-sprayed cylinder linings for vastly reduced internal friction. By returning to the perfect primary and secondary balance of a straight-six, Mercedes completely eliminated the heavy, parasitic balance shafts required in their older V6 diesels.",
      "crankshaft": "Forged steel, micro-alloyed crankshaft supported by 7 massive main bearings. Features incredibly precise counterweights to ensure perfectly smooth power delivery.",
      "pistonSpeed": "15.0 m/s @ 4600 RPM. Designed specifically for massive, effortless low-end torque. The OM656 utilizes advanced stepped-bowl forged steel pistons rather than aluminum, offering immense thermal stability and structural strength under high boost.",
      "alternator": "180A Bosch heavy-duty unit with advanced LIN-bus management.",
      "rotatingAssembly": { "pistonConstruction": "Heavy-duty forged steel pistons with an advanced stepped-bowl design for perfect combustion efficiency.", "wristPinDiameter": "32 mm.", "connectingRodLength": "148 mm.", "crankMainJournal": "65.0 mm.", "rodRatio": "1.65" },
      "cylinderHead": { "combustionChamberVol": "DOHC, 4-valve per cylinder.", "intakePortFlow": "Features advanced Camtronic variable valve timing exclusively on the exhaust camshaft to increase exhaust temperatures dynamically and rapidly heat up the SCR system.", "valveSizes": "Intake: 29.5 mm / Exhaust: 27.5 mm.", "lifterType": "Maintenance-free hydraulic bucket tappets." },
      "oilAndCooling": { "oilSquirters": "Yes, dedicated high-pressure jets target the internal cooling galleries of the steel pistons.", "oilPumpType": "Advanced fully variable displacement vane pump, optimizing pressure based on engine load to save fuel.", "thermostatOpening": "90°C (Electronically mapped).", "oilCooler": "Massive high-flow water-to-oil heat exchanger." },
      "fuelSystem": { "systemType": "Common-Rail Direct Injection (CDI) featuring highly advanced Selective Catalytic Reduction (SCR) via AdBlue injection.", "maxPressure": "2500 Bar.", "injectors": "Ultra-precise Piezo-electric injectors." },
      "tuningLimits": { "maxSafeTorqueStock": "850 Nm", "maxSafePowerStock": "420 hp", "weakestLink": "AdBlue dosing limits, DPF thermal capacity, and the rear simplex timing chain." },
      "electrical": { "coils": "N/A", "ecu": "Bosch MD1 managing the incredibly complex sequential turbo changeover logic, Camtronic system, and AdBlue dosing." }
    },
